  const box = { x: Number(attr(off, "x")), y: Number(attr(off, "y")), w: Number(attr(ext, "cx")), h: Number(attr(ext, "cy")) };
  return Object.values(box).every(Number.isFinite) ? { box, xfrm } : undefined;

